/// <summary>
/// Task 182820 CB272_SalesInvoicing
/// OnInitializing in event to disable and enable controls
/// </summary>
/// <param name="sender">TAMRebateTrans datasource</param>
/// <param name="e">TAMRebateTrans DataSource Event Args</param>
[FormEventHandler(formStr(TAMRebateTrans), FormEventType::Initialized),
 SuppressBPWarning('BPParameterNotUsed', 'The parameter e is not used.')]
public static void TAMRebateTrans_OnInitializing(xFormRun sender, FormEventArgs e)
{
    TAMRebateDateTrans rebateDateTrans = sender.args().record();

    if (rebateDateTrans)
    {
        METTAMRebateTransFormEventHandler::enableOrDisableMETControls(rebateDateTrans.RebateTransId, sender);
    }
}

/// <summary>
/// Task 182820 CB272_SalesInvoicing
/// Onactivated event to disable and enable controls
/// </summary>
/// <param name="sender">TAMRebateTrans datasource</param>
/// <param name="e">TAMRebateTrans DataSource Event Args</param>
[FormDataSourceEventHandler(formDataSourceStr(TAMRebateTrans, TAMRebateTrans), FormDataSourceEventType::SelectionChanged),
 SuppressBPWarning('BPParameterNotUsed', 'The parameter e is not used.')]
public static void TAMRebateTrans_OnSelectionChanged(FormDataSource sender, FormDataSourceEventArgs e)
{
    TAMRebateTrans rebateTrans = sender.cursor();

    if (rebateTrans)
    {
        METTAMRebateTransFormEventHandler::enableOrDisableMETControls(rebateTrans.RebateTransId, sender.formRun());
    }

}

/// <summary>
/// Helper class to enable or disable METControls based on parameters and others
/// </summary>
/// <param name = "_rebateTransId">TAMRebateTransId</param>
/// <param name = "_formRun">Formrun instance</param>
private static void enableOrDisableMETControls(TAMRebateTransId _rebateTransId, FormRun _formRun)
{
    TAMRebateDeal rebatedeal = TAMRebateDeal::find(TAMRebateDateTrans::find(_rebateTransId).RebateDeal);

    boolean followTransItemGSTGroup = TAMRebatePosting::find(rebateDeal.RebatePostingId, rebateDeal.ModuleInventCustVend).METFollowTransItemGSTGroup;

    if (followTransItemGSTGroup)
    {
        _formRun.design().controlName(formControlStr(TAMRebateTrans, TAMRebateTrans_METTaxItemGroup)).visible(true);
    }

    if (TAMRebateParameters::find().METProcessByCustRebateInvByItemType)
    {
        _formRun.design().controlName(formControlStr(TAMRebateTrans, TAMRebateTrans_METItemTypes)).visible(true);
    }
}
